create table public.players (id uuid primary key default gen_random_uuid(), public_slug text not null unique, display_name text not null check (length(display_name) between 2 and 80), avatar_path text, visibility text not null default 'public', merged_into_player_id uuid references public.players, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version bigint not null default 1);
create table public.accounts (id uuid primary key default gen_random_uuid(), auth_user_id uuid not null unique references auth.users(id) on delete cascade, player_id uuid not null unique references public.players(id), contact_verified_at timestamptz, created_at timestamptz not null default now());
create table public.clubs (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, timezone text not null, subscription_status public.subscription_status not null default 'trialing', subscription_valid_until timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version bigint not null default 1);
create table public.club_memberships (id uuid primary key default gen_random_uuid(), club_id uuid not null references public.clubs on delete cascade, player_id uuid not null references public.players, role public.club_role not null default 'member', status public.membership_status not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version bigint not null default 1, unique(club_id, player_id));
create index club_memberships_player_active_idx on public.club_memberships(player_id, club_id) where status='active';
create table public.identity_attestations (id uuid primary key default gen_random_uuid(), club_id uuid not null references public.clubs, player_id uuid not null references public.players, attested_by_player_id uuid not null references public.players, attestation_type text not null, note text, created_at timestamptz not null default now(), revoked_at timestamptz, unique(club_id, player_id, attestation_type));
create table private.platform_admins (auth_user_id uuid primary key references auth.users, granted_at timestamptz not null default now());
create trigger players_updated before update on public.players for each row execute function private.set_updated_at();
create trigger clubs_updated before update on public.clubs for each row execute function private.set_updated_at();
create trigger memberships_updated before update on public.club_memberships for each row execute function private.set_updated_at();
